  [
   ['तारीख और आगमन समय से शुरू करें', 'दा नांग अंतरराष्ट्रीय हवाई अड्डे (DAD) की उड़ानें खोजें और कुल यात्रा समय, सामान तथा आगमन समय तुलना करें। देर से पहुँचने पर देर से चेक-इन की अनुमति लें; सुबह जल्दी वापसी हो तो रहने और परिवहन की व्यवस्था उसी अनुसार करें। आखिरी सुबह दूर घूमने के बजाय वापसी उड़ान से पहले अतिरिक्त समय रखें।'],
   ['समुद्र दिखने वाला होटल ध्यान से चुनें', 'समुद्र तट के लिए माय खे और आन थुओंग तथा नदी किनारे शहर घूमने के लिए हान नदी क्षेत्र देखें। समुद्र दिखने वाला कमरा सीधे तट पर स्थित होटल जैसा नहीं होता। कमरे की श्रेणी, नक्शे पर स्थान, हाल की समीक्षा, नाश्ता और रद्द करने की शर्तें जाँचें। मूल पोस्ट में होटल के नाम या रेटिंग नहीं हैं, इसलिए इस लेख में होटल की रैंकिंग नहीं दी गई है।'],
   ['हर भ्रमण के लिए अलग समय रखें', 'बा ना हिल्स गोल्डन ब्रिज वाला पहाड़ी पर्यटन परिसर है; परिवहन, मौसम और टिकट में शामिल चीज़ें देखें। मार्बल माउंटेन्स में गुफाएँ, मंदिर, सीढ़ियाँ और असमतल रास्ते हैं; चलने की क्षमता और जूते ध्यान में रखें। होई आन की ऐतिहासिक गलियों और नदी किनारे के लिए अलग समय रखें। पिकअप स्थान, गाइड की भाषा, वापसी समय और प्रवेश शुल्क पूछें।'],
   ['उड़ान–होटल पैकेज और अलग बुकिंग तुलना करें', 'एक जैसी तारीख, यात्री संख्या, कमरे की श्रेणी, सामान और रद्द करने की शर्तों पर तुलना करें। हवाई अड्डे के परिवहन और कर भी जोड़ें। मूल पोस्ट सस्ती उड़ान और विशेष कीमत का प्रचार करती है, लेकिन तारीख वाला मूल्य या तुलना नहीं देती। मौजूदा वास्तविक ऑफर बुकिंग लिंक पर जाँचें।'],
   ['छोटी तैयारी सूची', 'पहले यात्रा दस्तावेज़ और प्रवेश नियम जाँचें, फिर उड़ान, ठहरना और हर दिन एक मुख्य गतिविधि चुनें। बुकिंग नंबर बचाएँ, हवाई अड्डे का परिवहन तय करें और नाव, समुद्र तट या पहाड़ जाने से पहले मौसम दोबारा देखें। नीचे का Trip.com लिंक मूल पोस्ट से लिया गया है; अंतिम कीमत और बुकिंग शर्तें सेवा प्रदाता बताता है।'],
  ]
